static void netsec_uninit_pkt_dring ( struct netsec_priv * priv , int id ) { struct netsec_desc_ring * dring = & priv -> desc_ring [ id ] ; struct netsec_desc * desc ; u16 idx ; for ( idx = 0 ; idx < DESC_NUM ; idx ++ ) { desc = & dring -> desc [ idx ] ; if ( ! desc -> addr ) { continue ; } if ( id == NETSEC_RING_RX ) { struct page * page = virt_to_page ( desc -> addr ) ; page_pool_put_full_page ( dring -> page_pool , page , false ) ; } if ( id == NETSEC_RING_TX ) { dma_unmap_single ( priv -> dev , desc -> dma_addr , desc -> len , DMA_TO_DEVICE ) ; dev_kfree_skb ( desc -> skb ) ; } } if ( id == NETSEC_RING_RX ) { if ( xdp_rxq_info_is_reg ( & dring -> xdp_rxq ) ) { xdp_rxq_info_unreg ( & dring -> xdp_rxq ) ; } page_pool_destroy ( dring -> page_pool ) ; } memset ( dring -> desc , 0 , sizeof ( netsec_desc ) * DESC_NUM ) ; memset ( dring -> vaddr , 0 , DESC_SZ * DESC_NUM ) ; dring -> head = 0 ; dring -> tail = 0 ; if ( id == NETSEC_RING_TX ) { netdev_reset_queue ( priv -> ndev ) ; } } 